let world=0,chosenNote='B5',activeLesson=null,selectedSong='curriculum-05',selectedSongLevel=1,segment='all',chunkBeats=8,scoreScale=1,scoreBaseWidth=0,audio=null,playing=false,timers=[],nodes=[],loop=false,clickTrack=false,articulation='normal',composerBeat=1,toastTimer,importCandidate=null;
