function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function earnedPoints(){return points(state);}
function badge(r){return !r?'○ これから':r.rating===1?'↻ れんしゅう中':r.rating===2?'✓ できた':'★ ばっちり';}
function route(p){stopAudio();page=p;location.hash=p;render();$('#main').focus();}
const nav=[['map','◈','ぼうけんマップ'],['songs','♫','曲のひろば'],['fingers','☝','指づかい図かん'],['lab','⚗','つくる・調べる'],['stamps','✦','スタンプ帳']];
function shell(body){const xp=earnedPoints(),lv=Math.floor(xp/100)+1;return `<aside class="sidebar"><a class="brand" href="#map" data-page="map"><span class="brand-icon">♫</span><span>リコーダー<br><b>クエスト<span class="brand-star">✦</span></b></span></a><div class="instrument-pill">AULOS 702B(G)<br>ソプラノ・ジャーマン式</div><nav aria-label="メインメニュー">${nav.map(([p,i,l])=>`<button class="nav-item ${page===p?'selected':''}" data-page="${p}" ${page===p?'aria-current="page"':''}><span aria-hidden="true">${i}</span>${l}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="practice-tip"><b>きょうも、自分のペースで。</b><p>できない日も、発見はある。<br>ひとつずつ進もう。</p></div><button class="nav-item ${page==='guide'?'selected':''}" data-page="guide"><span aria-hidden="true">⚙</span>先生へ・記録の設定</button></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">音のぼうけん <span>/</span> ${nav.find(n=>n[0]===page)?.[2]||'先生へ・記録の設定'}</span><div class="player-meta"><span class="level-pill">Lv. ${lv}</span><b class="xp-pill">✦ ${xp} <small>ポイント</small></b><span class="avatar" aria-label="自分の学習">♪</span></div></header>${storageProblem?'<div class="storage-warning" role="alert">保存済みの記録を読み込めないか、この端末に保存できません。設定からバックアップを確認してください。</div>':''}<main id="main" tabindex="-1">${body}</main><footer>リコーダークエスト <span>｜</span> くらべるのは、きのうの自分。 <span>｜</span> 記録はこのブラウザに保存されます</footer></div><dialog id="lesson-dialog" aria-labelledby="lesson-title"></dialog><dialog id="confirm-dialog" aria-labelledby="confirm-title"></dialog>`;}
function heading(k,t,s){return `<div class="page-heading"><div><p class="eyebrow">${k}</p><h1>${t}</h1><p class="muted">${s}</p></div></div>`;}
function mapView(){const rec=recommend(state),w=WORLDS[world],list=LESSONS.filter(l=>l.world===world),done=completed(state);const here=list.filter(l=>(state.records[l.id]?.rating||0)>=2).length;return `${heading('LET’S PLAY','きょうは、どんな音に出会う？','１つのチャレンジは３〜５分。気になるところから始めてもいいよ。')}<div class="dashboard-top"><section class="next-quest"><div><span class="white-chip">✦ きみへのおすすめ</span><p class="next-label">${WORLDS[rec.lesson.world].title} ・ STEP ${String(rec.lesson.number).padStart(2,'0')}</p><h2>${esc(rec.lesson.title)}</h2><p>${esc(rec.lesson.goal)}</p><button class="button yellow" data-lesson="${rec.lesson.id}">このチャレンジをはじめる <span>→</span></button></div><div class="quest-emblem" aria-hidden="true"><span>♪</span><span>✦</span><b>${String(rec.lesson.number).padStart(2,'0')}</b><small>STEP</small></div></section><section class="progress-card"><span class="eyebrow">MY ADVENTURE</span><h2>ここまでの足あと</h2><div class="progress-summary"><div class="ring" style="--progress:${done/LESSONS.length*100}%"><b>${done}<small>/ ${LESSONS.length}</small></b></div><div><b>${Math.floor(earnedPoints()/100)+1}<small> レベル</small></b><p>${Object.values(state.records).filter(r=>r.rating===3).length} 個の「ばっちり」</p></div></div><p class="recommend-reason">${rec.reason}</p><button class="text-button" data-page="stamps">スタンプ帳をひらく ↗</button></section></div><div class="section-title"><div><h2>ぼうけんマップ</h2><span>学年は目安。おさらいも、先への挑戦も自由！</span></div><span class="count-pill">12 エリア</span></div><div class="world-grid">${WORLDS.map(x=>{const n=LESSONS.filter(l=>l.world===x.id&&(state.records[l.id]?.rating||0)>=2).length;return `<button class="world-card ${world===x.id?'active':''}" style="--world:${x.color}" data-world="${x.id}" aria-pressed="${world===x.id}"><span class="world-icon" aria-hidden="true">${x.icon}</span><span class="world-text"><small>AREA ${String(x.id+1).padStart(2,'0')} <span>${n}/8</span></small><b>${x.title}</b><span>${x.grade}</span></span><span class="mini-progress" style="--fill:${n/8*100}%"></span></button>`;}).join('')}</div><section class="area-panel" style="--world:${w.color}"><div class="area-heading"><div><span class="area-kicker">AREA ${String(world+1).padStart(2,'0')} <span>${w.grade}</span></span><h2>${w.icon} ${w.title}</h2><p>${w.sub}</p></div><div class="area-progress"><b>${here}<small> / 8 クリア</small></b><progress max="8" value="${here}" aria-label="このエリアの進み具合"></progress></div></div><div class="lesson-grid">${list.map(l=>{const r=state.records[l.id];return `<button class="lesson-card ${r?.rating>=2?'done':''}" data-lesson="${l.id}"><span class="step-round ${r?.rating>=2?'checked':''}">${r?.rating>=2?'✓':String(l.number).padStart(2,'0')}</span><span class="lesson-copy"><small>${l.minutes}分 ・ ${l.number===8?'まとめの挑戦':'小さな一歩'}</small><b>${l.title}</b><span>${badge(r)}</span></span><span class="lesson-arrow">›</span></button>`;}).join('')}</div></section>`;}
function fingering(note=chosenNote,compact=false){const [name,,pattern]=NOTES[note];if(!pattern)return `<div class="fingering ${compact?'compact':''}"><h3>${esc(name)}</h3><p>この音は、702B(G)に付属する運指表を先生と確認してから吹こう。</p><p>この機種の指の形は確認中です。</p></div>`;const labels=['左・親指（うら０）','左・人さし指（１）','左・中指（２）','左・薬指（３）','右・人さし指（４）','右・中指（５）','右・薬指（６）','右・小指（７）'];return `<div class="fingering ${compact?'compact':''}"><div class="finger-title"><span class="eyebrow">GERMAN・基本運指</span><h3>${name}</h3></div><div class="hole-list">${[...pattern].map((v,i)=>`<div class="hole-row ${i===4?'hand-break':''}"><span class="hole-number">${i}</span><span class="${i>=6?'double-holes':'single-hole'}">${i>=6?`<i class="hole ${v==='1'||v==='p'?'closed':''}"></i><i class="hole ${v==='1'?'closed':''}"></i>`:`<i class="hole ${v==='1'?'closed':v==='h'?'half':''}"></i>`}</span><span>${labels[i]}</span><span class="sr-only">${v==='1'?'閉じる':v==='h'?'少し開ける':v==='p'?'2つの小穴の大きい方だけ閉じる':'開ける'}</span></div>`).join('')}</div><div class="finger-legend"><span>● 閉じる</span><span>○ 開ける</span><span>◐ 少し開ける</span><span>●○ 小穴の大きい方だけ閉じる</span></div>${pattern[0]==='h'?'<p class="finger-tip">うら０は、小さなすきま。半分きっちり開けなくていいよ。</p>':''}${FINGERING_CAVEATS[note]?`<p class="finger-tip">${esc(FINGERING_CAVEATS[note])}</p>`:''}<p class="finger-tip">702B(G)の付属表と見くらべよう。<br>右の親指は、うらで楽器を支えるよ。</p></div>`;}
const diatonic={C:0,D:1,E:2,F:3,G:4,A:5,B:6};
function staff(events,meter=4,pickup=0){const measures=measuresFor(events,meter,pickup);return `<div class="score-grid" aria-label="楽譜。音符を押すと指づかいを確認できます">${measures.map((m,mi)=>{const accidentals={};return `<svg class="measure" viewBox="0 -35 310 192" role="group" aria-label="${pickup&&mi===0?'弱起':mi+(pickup?0:1)+'小節'}"><text x="12" y="18" class="measure-number">${pickup&&mi===0?'弱起':mi+(pickup?0:1)}</text>${[60,70,80,90,100].map(y=>`<line x1="12" x2="302" y1="${y}" y2="${y}" class="staff-line"/>`).join('')}<line x1="302" x2="302" y1="60" y2="100" class="bar-line"/>${mi===0?`<text x="14" y="94" class="clef">𝄞</text><text x="39" y="76" class="time-signature">${meter}</text><text x="39" y="94" class="time-signature">4</text>`:''}${m.map(e=>{const weight=m.reduce((a,n)=>a+Math.max(1,n.beats),0);const before=m.slice(0,m.indexOf(e)).reduce((a,n)=>a+Math.max(1,n.beats),0);const x=(mi===0?67:31)+before*(mi===0?225:263)/weight;const label=e.note==='R'?'休み':NOTES[e.note][0];const y=e.note==='R'?80:110-(diatonic[e.note[0]]+(Number(e.note.match(/\d+$/)?.[0])-5)*7)*5;const pitch=e.note==='R'?'':e.note[0]+e.note.match(/\d+$/)?.[0];const altered=e.note.includes('#')?'♯':e.note.includes('b')?'♭':'';const accidental=e.note==='R'?'':altered|| (accidentals[pitch]?'♮':'');if(pitch)accidentals[pitch]=altered;const nextX=x+Math.max(1,e.beats)*(mi===0?225:263)/weight;const down=y<80;const stemX=x+(down?-6:6),endY=y+(down?31:-31);return `<g class="score-note" data-note="${e.note}" data-event="${e.index}" role="button" tabindex="0" aria-label="${label}、${e.beats}拍"><rect class="note-hit" x="${x-15}" y="-28" width="30" height="170" rx="9"/>${e.note==='R'?`<text x="${x-9}" y="91" class="rest">${e.beats>=4?'𝄻':e.beats>=2?'𝄼':e.beats<=.25?'𝄿':e.beats<1?'𝄾':'𝄽'}</text>${[.75,1.5,3].includes(e.beats)?`<circle cx="${x+13}" cy="80" r="2.2"/>`:""}`:`${accidental?`<text x="${x-21}" y="${y+5}" class="accidental">${accidental}</text>`:""}${y>=110?Array.from({length:Math.floor((y-100)/10)},(_,i)=>`<line x1="${x-11}" x2="${x+11}" y1="${110+i*10}" y2="${110+i*10}" class="staff-line"/>`).join(''):y<=50?Array.from({length:Math.floor((60-y)/10)},(_,i)=>`<line x1="${x-11}" x2="${x+11}" y1="${50-i*10}" y2="${50-i*10}" class="staff-line"/>`).join(''):''}<ellipse cx="${x}" cy="${y}" rx="7" ry="5" transform="rotate(-18 ${x} ${y})" class="note-head ${e.beats>=2?'open':''}"/>${e.beats<4?`<line x1="${stemX}" x2="${stemX}" y1="${y}" y2="${endY}" class="stem"/>`:''}${e.beats<1?`<path d="M${stemX} ${endY} q 17 ${down?-3:3} 10 ${down?-20:20}" class="flag"/>${e.beats<=.25?`<path d="M${stemX} ${endY+(down?-7:7)} q 17 ${down?-3:3} 10 ${down?-20:20}" class="flag"/>`:''}`:''}${[.75,1.5,3].includes(e.beats)?`<circle cx="${x+13}" cy="${y-3}" r="2.2"/>`:''}${e.tieOut?`<path d="M${x+8} ${y+15} Q${(x+nextX)/2} ${y+27} ${m.indexOf(e)===m.length-1?301:nextX-8} ${y+15}" class="tie"/>`:''}${e.tieIn&&m.indexOf(e)===0?`<path d="M12 ${y+15} Q20 ${y+27} ${x-8} ${y+15}" class="tie"/>`:''}`}<text x="${x}" y="139" text-anchor="middle" class="note-label">${state.settings.names?(e.note==='R'?'休み':({C:'ド',D:'レ',E:'ミ',F:'ファ',G:'ソ',A:'ラ',B:'シ'}[e.note[0]]+(e.note.includes('#')?'♯':e.note.includes('b')?'♭':'')+(e.note.endsWith('7')?'↑↑':e.note.endsWith('6')?'↑':''))):''}</text></g>`;}).join('')}</svg>`;}).join('')}</div>`;}
function player(events,meter=4,zoomable=false,pickup=0){const duet=!activeLesson&&page==='songs'&&ALL_SONGS.find(s=>s.id===selectedSong)?.secondVoice;const score=(duet?`<h3>${duetPart==='2'?'第2パート：長い音の伴奏':'第1パート：旋律'}</h3>`:'')+staff(events,meter,pickup)+(duet&&duetPart==='both'&&segment!=='drill'?`<h3>第2パート：長い音の伴奏</h3>${staff(selectedWindow('2').events,meter,pickup).replaceAll('data-event=', 'data-secondary-event=')}`:''),zoom=zoomable?`<div class="score-view-tools" aria-label="楽譜の表示倍率"><button class="button secondary" data-action="score-fit">↔ 全体を画面に合わせる</button><button class="zoom-button" data-action="score-out" aria-label="楽譜を縮小">−</button><output id="score-zoom-output" aria-live="polite">${Math.round(scoreScale*100)}%</output><button class="zoom-button" data-action="score-in" aria-label="楽譜を拡大">＋</button><button class="text-button" data-action="score-reset">100%</button></div><div class="score-viewport"><div class="score-zoom-surface" style="--score-zoom:${scoreScale}${scoreBaseWidth&&scoreScale!==1?`;width:${scoreBaseWidth}px`:""}">${score}</div></div>`:score;return `<div class="audio-controls"><button class="button primary play-toggle" data-action="play">▶ お手本を聴く</button><button class="button secondary" data-action="stop">■ とめる</button><label class="tempo">速さ <input id="tempo" type="range" min="40" max="140" step="1" value="${state.settings.tempo}" aria-label="演奏の速さ"><output>${state.settings.tempo}</output></label><label class="check-inline"><input type="checkbox" id="loop" ${loop?'checked':''}>くり返す</label><label class="check-inline"><input type="checkbox" id="click-track" ${clickTrack?'checked':''}>拍の音</label><button class="text-button" data-action="names">音名を${state.settings.names?'かくす':'出す'}</button></div><div class="player-status" role="status" aria-live="polite">${pickup?`${meter}拍を数え、次の小節の${meter-pickup+1}拍目からスタート。`:`${meter}拍 数えてからスタート。`}お手本は音の高さ・長さを確かめる電子音です。</div>${zoom}`;}
function setScoreScale(value){
  scoreScale=Math.max(.01,Math.min(1.5,Math.round(value*1000)/1000));
  const surface=$('.score-zoom-surface'),out=$('#score-zoom-output'),viewport=$('.score-viewport');
  if(surface){
    if(viewport){scoreBaseWidth=Math.max(1,viewport.clientWidth-20);surface.style.setProperty('width',`${scoreBaseWidth}px`);}
    surface.style.setProperty('--score-zoom',scoreScale);
  }
  if(out)out.value=`${Math.round(scoreScale*100)}%`;
}
function fitScore(){const viewport=$('.score-viewport'),surface=$('.score-zoom-surface');if(!viewport||!surface)return;setScoreScale(1);surface.style.setProperty('width',`${Math.max(1,viewport.clientWidth-20)}px`);requestAnimationFrame(()=>{const width=Math.max(1,viewport.clientWidth-20),height=Math.max(1,Math.min(viewport.clientHeight-20,innerHeight-viewport.getBoundingClientRect().top-28));setScoreScale(fitScale(width,height,surface.scrollWidth,surface.scrollHeight));toast(`楽譜を ${Math.round(scoreScale*100)}% で表示します。小さければ2小節ずつ練習しよう。`);});}
function selectedWindow(voice=duetPart){const song=ALL_SONGS.find(s=>s.id===selectedSong);if(!song?.notes)return {events:[],pickup:0};if(segment==='drill')return {events:parseNotes(voice==='2'&&song.secondVoice?'C5 G5':song.pair||song.notes).map(e=>({...e,beats:2})),pickup:0};return practiceWindow(parseNotes(voice==='2'&&song.secondVoice?song.secondVoice:song.notes),song.meter||4,song.pickup||0,segment,chunkBeats);}
function currentEvents(){if(activeLesson)return parseNotes(activeLesson.notes);if(page==='lab')return state.composition;if(page==='songs')return selectedWindow().events;return [{note:chosenNote,beats:2}];}
function currentMeter(){if(activeLesson)return activeLesson.meter||(activeLesson.id==='w3-6'||activeLesson.world===6&&activeLesson.number===8?3:4);return page==='songs'?(ALL_SONGS.find(s=>s.id===selectedSong)?.meter||4):4;}
function currentPickup(){return !activeLesson&&page==='songs'?selectedWindow().pickup:0;}
function updateNote(note){if(!NOTES[note])return;chosenNote=note;$$('.live-fingering').forEach(e=>e.innerHTML=fingering(note,true));$$('[data-pick-note]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.pickNote===note)));}
async function ctx(){if(!audio){const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error('このブラウザでは音を再生できません');audio=new A();}if(audio.state==='suspended')await audio.resume();return audio;}
function tone(note,when,duration,isClick=false){if(note==='R')return;const o=audio.createOscillator(),g=audio.createGain();o.type=isClick?'sine':'sine';o.frequency.value=isClick?1000:440*2**((NOTES[note][1]-69)/12);g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(isClick?.09:.12,when+.012);g.gain.setValueAtTime(isClick?.09:.12,when+Math.max(.013,duration-.03));g.gain.linearRampToValueAtTime(0,when+duration);o.connect(g);g.connect(audio.destination);o.start(when);o.stop(when+duration+.02);nodes.push(o);o.onended=()=>{o.disconnect();g.disconnect();nodes=nodes.filter(n=>n!==o);};}
function stopAudio(){audioGeneration++;timers.forEach(clearTimeout);timers=[];for(const n of nodes){try{n.stop();}catch{}}nodes=[];playing=false;$$('.score-note').forEach(e=>e.classList.remove('sounding'));$$('.play-toggle').forEach(e=>{e.textContent='▶ お手本を聴く';e.disabled=false;});$$('.player-status').forEach(e=>e.textContent='とめました。ゆっくり何度でも試そう。');}
async function play(){stopAudio();const generation=audioGeneration;const events=currentEvents();if(!events.length){toast('まず音を入れてみよう。');return;}try{await ctx();if(generation!==audioGeneration)return;const beat=60/state.settings.tempo,meter=currentMeter(),start=audio.currentTime+.1;playing=true;$$('.play-toggle').forEach(e=>{e.disabled=true;e.textContent='♫ 再生中';});for(let i=0;i<meter;i++){tone('B5',start+i*beat,.055,true);timers.push(setTimeout(()=>$$('.player-status').forEach(e=>e.textContent=`じゅんび… ${i+1}`),100+i*beat*1000));}const pickup=currentPickup();const count=meter+(pickup?meter-pickup:0);for(let i=meter;i<count;i++)tone('B5',start+i*beat,.055,true);if(!activeLesson&&page==='songs'&&duetPart==='both'&&segment!=='drill'&&ALL_SONGS.find(s=>s.id===selectedSong)?.secondVoice){let secondTime=count*beat;for(const e of selectedWindow('2').events){tone(e.note,start+secondTime,e.beats*beat*.85);secondTime+=e.beats*beat;}}let time=count*beat;events.forEach((e,i)=>{tone(e.note,start+time,e.beats*beat*(articulation==='short'?.4:articulation==='smooth'?.98:.85));timers.push(setTimeout(()=>{$$('.score-note').forEach(n=>n.classList.toggle('sounding',Number(n.dataset.event)===i));updateNote(e.note);$$('.player-status').forEach(n=>n.textContent=e.note==='R'?'お休み。拍を数えよう。':`${NOTES[e.note][0]} ・ ${e.beats}拍`);},100+time*1000));time+=e.beats*beat;});if(clickTrack){for(let i=count;i<time/beat;i++)tone('B5',start+i*beat,.04,true);}timers.push(setTimeout(()=>{stopAudio();if(loop)play();else $$('.player-status').forEach(e=>e.textContent='最後まで聴けたね。次は自分の音で試そう。');},time*1000+200));}catch(e){stopAudio();toast(e.message||'音を再生できません。音量とブラウザの設定を確認してね。');}}
async function singleNote(n){stopAudio();const generation=audioGeneration;updateNote(n);try{await ctx();if(generation!==audioGeneration)return;tone(n,audio.currentTime+.02,.7);}catch(e){toast(e.message);}}
function openLesson(id){const l=LESSONS.find(l=>l.id===id);if(!l)return;stopAudio();activeLesson=l;const r=state.records[id];const note=parseNotes(l.notes).find(e=>e.note!=='R')?.note||'B5';chosenNote=note;const dialog=$('#lesson-dialog');dialog.innerHTML=`<div class="modal-header"><div><span class="eyebrow">${WORLDS[l.world].title} / STEP ${l.number}</span><h2 id="lesson-title">${l.title}</h2></div><button class="icon-button" data-action="close-lesson" aria-label="チャレンジを閉じる">×</button></div><div class="modal-body"><div class="lesson-goal"><span>きょうのミッション</span><b>${l.goal}</b><small>${l.minutes}分くらい ・ 何度やり直しても大丈夫</small></div><div class="lesson-layout"><div><h3>① ひとつずつ、やってみよう</h3><div class="microsteps">${l.steps.map((s,i)=>`<label><input type="checkbox" class="step-check"><span class="step-index">${i+1}</span><span>${s}</span></label>`).join('')}</div><div class="hint"><b>💡 こまったら</b><p>${l.tip}</p></div>${l.world===11&&l.number<=3?`<p><a class="button secondary" href="${PDF}" target="_blank" rel="noopener">アウロスのドイツ式運指表（販売店転載） ↗</a></p><p class="muted">下の音は準備練習です。調べる半音・超高音の音源ではありません。</p>`:''}<h3>② 音を聴く・指をたしかめる</h3>${player(parseNotes(l.notes),currentMeter())}<div class="hint inquiry"><b>🔎 発見のたね</b><p>${l.question}</p></div></div><aside class="live-fingering">${fingering(note,true)}</aside></div><section class="reflection"><h3>③ ふりかえろう</h3><p class="success-criterion"><b>できたの目安</b> ${l.check}</p><fieldset class="rating"><legend>今の自分に近いものは？</legend><label><input name="rating" type="radio" value="1"><span>↻<b>むずかしい</b><small>ひとつ戻って練習</small></span></label><label><input name="rating" type="radio" value="2"><span>✓<b>できた！</b><small>目安をクリア</small></span></label><label><input name="rating" type="radio" value="3"><span>★<b>ばっちり！</b><small>もう一度もできた</small></span></label></fieldset><label class="field-label" for="reflection">気づいたこと・次に試したいこと（書けたら）</label><textarea id="reflection" maxlength="800" rows="2" placeholder="例：右の指を置くと、左の指がずれることに気づいた。">${esc(r?.reflection||'')}</textarea><p class="muted">自分でふりかえる記録です。音の自動採点ではありません。</p><div class="save-row"><span id="save-hint">「むずかしい」は途中でも記録できるよ。</span><button class="button primary" id="save-lesson" data-action="save-lesson" disabled>足あとをのこす ✦</button></div></section></div>`;dialog.showModal();}
function closeLesson(){stopAudio();$('#lesson-dialog').close();activeLesson=null;}
function checkLesson(){const rating=Number($('input[name="rating"]:checked')?.value||0);const all=$$('.step-check').every(e=>e.checked);$('#save-lesson').disabled=!rating||(rating>=2&&!all);$('#save-hint').textContent=rating>=2&&!all?'３つのステップを試したら、チェックを入れてね。':'くり返し練習してもポイントは重複しません。';}
function saveLesson(){if($('#save-lesson').disabled||!activeLesson)return;const l=activeLesson,rating=Number($('input[name="rating"]:checked').value),before=earnedPoints();record(state,l.id,rating,$('#reflection').value);save();const diff=earnedPoints()-before;closeLesson();render();toast(rating===1?'挑戦したことが一歩前進！おすすめにおさらいを用意したよ。':`足あとをのこしたよ！${diff>0?' ＋'+diff+'ポイント ✦':' 次も自分のペースで。'}`);}
function songSteps(s){if(!s.steps?.length)return'';const checks=state.songSteps?.[s.id]||[];return `<h3>${s.steps.length}つの小さなステップ</h3><div class="microsteps song-steps">${s.steps.map((step,i)=>`<label><input type="checkbox" data-song-step="${i}" ${checks[i]?'checked':''}><span class="step-index">${i+1}</span><span>${esc(step)}</span></label>`).join('')}</div>`;}
function canRateSong(s){return segment==='all'&&s.steps.every((_,i)=>state.songSteps?.[s.id]?.[i]);}
function songSelfRating(s){if(!s.songLevel||s.mode!=='play')return'';const r=state.songRecords?.[s.id],ready=canRateSong(s);return `<section class="song-reflection"><h3>今日の演奏スタンプ</h3><p><b>できたの目安：</b>${esc(s.criterion)}</p><p class="rating-help">部分練習の後は「収録部分を通す」を選び、6つの手順を試してから記録しよう。曲全体ではなく、上に書かれた収録範囲の記録です。</p><div class="song-rating" role="group" aria-label="${esc(s.title)}の自己評価">${[[1,'↻','れんしゅう中'],[2,'✓','できた！'],[3,'★','ばっちり！']].map(([value,mark,label])=>`<button data-rate-song="${value}" ${value>1&&!ready?'disabled':''} class="${r?.rating===value?'active':''}" aria-pressed="${r?.rating===value}">${mark}<b>${label}</b><small>${value*5} pt</small></button>`).join('')}</div><p>「ばっちり」は、できた理由や工夫を友達に説明できたとき。最高到達分だけ、1曲最大15ポイント。</p></section>`;}
function songsView(){
  if(selectedSongLevel&&!songLevelUnlocked(state,selectedSongLevel)){selectedSongLevel=1;selectedSong='curriculum-05';segment='all';}
  const levelSongs=selectedSongLevel===0?ALL_SONGS.filter(song=>song.songLevel===0):CURRICULUM_SONGS.filter(song=>song.songLevel===selectedSongLevel);
  let s=levelSongs.find(song=>song.id===selectedSong)||levelSongs.find(song=>song.mode==='play')||levelSongs[0];selectedSong=s.id;
  const all=s.notes?parseNotes(s.notes):[],total=all.reduce((n,e)=>n+e.beats,0);
  const levels=SONG_LEVELS.map(level=>{const progress=songProgress(state,level.id),unlocked=songLevelUnlocked(state,level.id),available=CURRICULUM_SONGS.filter(s=>s.songLevel===level.id&&s.mode==='play').length;return `<button class="song-level ${selectedSongLevel===level.id?'active':''} ${unlocked?'':'locked'}" style="--level:${level.color}" data-song-level="${level.id}" aria-pressed="${selectedSongLevel===level.id}" aria-disabled="${!unlocked}"><span>${unlocked?'♫':'🔒'}</span><small>LEVEL ${level.id}</small><b>${level.title}</b><em>${available?`${progress}/${available} 収録分できた`:'楽譜の準備中'}</em></button>`;}).join('');
  const list=levelSongs.map(song=>{const r=state.songRecords?.[song.id];return `<button class="song-item ${song.id===selectedSong?'active':''}" data-song="${song.id}" aria-pressed="${song.id===selectedSong}"><span class="song-icon" style="--world:${song.songLevel?SONG_LEVELS[song.songLevel-1].color:WORLDS[song.world].color}">${r?.rating===3?'★':r?.rating>=2?'✓':'♫'}</span><span><small>${song.mode==='play'?'♫ 楽譜あり':'楽譜の準備中'}</small><b>${esc(song.title)}</b><small>${song.mode==='play'?esc(song.grade||'3〜6年生'):esc(song.kind)}</small></span></button>`;}).join('');
  const sourceLink=s.sourceUrl?`<a href="${s.sourceUrl}" target="_blank" rel="noopener">教科書との対応 ↗</a>`:'';
  const facts=`<dl class="song-facts"><div><dt>使う音</dt><dd>${esc(s.requiredNotes)}</dd></div><div><dt>注目</dt><dd>${esc(s.skill||s.focus)}</dd></div></dl>`;
  const bookDetail=`<div class="book-practice"><div class="book-callout"><span aria-hidden="true">▤</span><div><b>この曲の楽譜は準備中です</b><p>この画面だけでは原曲の練習はできません。今すぐ吹ける「楽譜あり」の曲を選ぼう。</p></div></div><button class="button secondary" data-action="ready-song">楽譜のある曲へ →</button>${s.review?`<details><summary>先生へ：この曲の確認状況</summary><p>${esc(s.review.creator)}</p><p>${esc(s.review.reason)}</p><p>${esc(s.review.rangeStatus)}</p><a href="${s.review.sourceUrl}" target="_blank" rel="noopener">確認先 ↗</a></details>`:''}<details><summary>先生と手元の楽譜で練習するとき</summary>${facts}<ol>${s.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details></div>`;
  const window=selectedWindow();
  const playDetail=`${facts}<p class="score-edition"><b>収録範囲：</b>${esc(s.scope||'練習用単旋律')} ／ ${esc(s.keyLabel||'調号なし')} ／ ${total}拍</p>${s.prereq?`<button class="text-button" data-lesson="${s.prereq}">使う音がむずかしいとき：先に指と音を練習 →</button>`:''}<div class="song-options">${s.secondVoice?`<label>パート <select id="duet-part">${[['1','第1パート：旋律'],['2','第2パート：伴奏'],['both','2人で合わせる']].map(([v,l])=>`<option value="${v}" ${duetPart===v?'selected':''}>${l}</option>`).join('')}</select></label>`:''}<label>区切る長さ <select id="chunk-beats">${(s.meter===2?[[2,'2拍'],[4,'4拍（2小節）']]:[[2,'2拍'],[4,'4拍'],[s.meter*2,'2小節']]).map(([n,label])=>`<option value="${n}" ${n===chunkBeats?'selected':''}>${label}</option>`).join('')}</select></label><label>練習するところ <select id="segment"><option value="all" ${segment==='all'?'selected':''}>収録部分を通す</option>${s.pair?`<option value="drill" ${segment==='drill'?'selected':''}>苦手な指の練習（1音2拍）</option>`:''}${Array.from({length:Math.ceil(total/chunkBeats)},(_,i)=>`<option value="${i}" ${segment===String(i)?'selected':''}>先頭から${i*chunkBeats}拍後〜${Math.min(total,(i+1)*chunkBeats)}拍後</option>`).join('')}</select></label><label>音のつなぎ方 <select id="articulation"><option value="normal" ${articulation==='normal'?'selected':''}>ふつう</option><option value="short" ${articulation==='short'?'selected':''}>短く</option><option value="smooth" ${articulation==='smooth'?'selected':''}>なめらか</option></select></label></div><div class="score-with-fingers"><div>${player(window.events,s.meter||4,true,window.pickup)}<p class="muted">途中で区切った音は、残りの長さで吹き始めます。音価は変えず、速さのつまみでゆっくりにしよう。</p>${songSteps(s)}<div class="hint inquiry"><b>🔎 調べてみよう</b><p>${esc(s.question||'最後の音を変えると、終わった感じは変わる？')}</p></div>${s.id==='frog'||s.id==='brother'?'<button class="button secondary" data-action="canon">♫ 輪唱を聴く（８拍あとに２人目）</button>':''}</div><aside class="live-fingering">${fingering(chosenNote,true)}</aside></div>${s.edition?`<details class="score-source"><summary>採用した旋律・変更点・出典</summary><p>${esc(s.edition)}</p><a href="${s.scoreSourceUrl}" target="_blank" rel="noopener">旋律の参照先 ↗</a><p>この楽譜は本サイトで記譜した単旋律です。参照先の画像・伴奏・音源は使っていません。教科書や歌集の掲載版と調・音価・反復が異なる場合があります。</p></details>`:''}`;
  return `${heading('MUSIC LIBRARY','曲のひろば','楽譜のある曲から、小さく区切って挑戦しよう。学年とレベルは目安だよ。')}<div class="song-unlock-note">40曲の候補のうち、${CURRICULUM_SONGS.filter(s=>s.mode==='play').length}曲に練習用の楽譜があります。次のレベルは、今のレベルの収録曲を3曲（3曲未満なら収録曲すべて）達成すると開きます。先生は設定で全曲を開けます。</div><div class="song-levels" aria-label="曲のレベルを選ぶ">${levels}<button class="song-level free ${selectedSongLevel===0?'active':''}" data-song-level="0" aria-pressed="${selectedSongLevel===0}"><span>∞</span><small>FREE</small><b>自由練習</b><em>創作・伝承曲12曲</em></button></div><div class="song-layout"><section class="song-list" aria-label="曲を選ぶ">${list}</section><section class="song-detail"><span class="eyebrow">${s.songLevel?`LEVEL ${s.songLevel} ・ `:''}${esc(s.grade||s.kind)}${s.meter?` ・ ${s.meter}/4拍子`:''}</span><h2>${esc(s.title)}</h2><p class="muted">${esc(s.source)} ${sourceLink}</p>${s.songLevel?`<div class="song-mission"><b>ミッション</b><span>${esc(s.goal)}</span></div>`:''}${s.mode==='book'?bookDetail:playDetail}${songSelfRating(s)}<p class="rights-note">${esc(s.rightsNote||'練習用の単旋律と電子音です。')}</p></section></div>`;
}
function fingersView(){return `${heading('FINGERING BOOK','指づかい図かん','音をえらぶと、指づかいと高さをたしかめられるよ。')}<div class="finger-book"><section><div class="note-picker">${Object.entries(NOTES).map(([k,n])=>`<button data-pick-note="${k}" aria-pressed="${k===chosenNote}"><span>♪</span><b>${n[0]}</b></button>`).join('')}</div><div class="hint"><b>指のやくそく</b><p>左手が上、右手が下。裏の穴は０、表は上から１〜７。６と７にある２つの小穴は、図が●●なら両方を閉じるよ。</p></div><h2>音がうまく出ないときは？</h2><details><summary>ピーッと高い音になる</summary><p>穴のすきまを一つずつ確認しよう。次に、息を少しやさしくして短く吹いてみよう。両方をいっぺんに変えず、一つずつ試そう。</p></details><details><summary>指を動かすと、音がまざる</summary><p>音を出さずに２つの指の形を交互につくろう。動かさない指はそのまま。ゆっくりできてから息を入れよう。</p></details><details><summary>高い音のすきまがわからない</summary><p>高いレは裏を全開。高いミからは裏に小さなすきまをつくるよ。図の◐は「半分の量」ではなく、少し開けるしるし。</p></details><details><summary>半音や、もっと高い音を調べたい</summary><p>低いド〜最高音のレの27音を表示します。高いミ以上は先生と少しずつ練習しよう。最高音域のド♯は資料で裏穴の指定が違うため、702B(G)の付属表を優先します。</p><a href="${PDF}" target="_blank" rel="noopener">アウロスのドイツ式運指表（販売店転載） ↗</a></details><p class="source-note">参照：<a href="${SOURCE}" target="_blank" rel="noopener">AULOS「ソプラノ・ハーカ702B(G)」</a>。27音をアウロスのドイツ式公開表（販売店転載）と照合しました。702B(G)の実機による確認ではありません。付属表を優先します。</p></section><aside class="live-fingering finger-large">${fingering(chosenNote)}</aside></div>`;}
function labView(){const notes=state.composition,total=notes.reduce((n,e)=>n+e.beats,0);return `${heading('SOUND LAB','つくる・調べる','「もし、こうしたら？」を音で試す場所。正解はひとつじゃないよ。')}<div class="lab-layout"><section class="composer"><span class="eyebrow">MY MELODY</span><h2>きみだけのメロディー</h2><label class="field-label" for="composition-title">曲の名前</label><input id="composition-title" maxlength="60" value="${esc(state.compositionTitle)}"><div class="composer-toolbar"><label>次に入れる音の長さ <select id="composer-beat">${[[.25,'¼拍'],[.5,'½拍'],[1,'１拍'],[1.5,'1½拍'],[2,'２拍'],[3,'３拍'],[4,'４拍']].map(([v,l])=>`<option value="${v}" ${v===composerBeat?'selected':''}>${l}</option>`).join('')}</select></label><span>${total}拍 ・ ${notes.length}/32音</span></div><div class="composer-keys">${Object.entries(NOTES).map(([k,n])=>`<button data-add-note="${k}" ${notes.length>=32?'disabled':''}>${n[0]}</button>`).join('')}<button data-add-note="R" ${notes.length>=32?'disabled':''}>休み</button></div><div class="composition-chips">${notes.length?notes.map((e,i)=>`<button data-remove-note="${i}" aria-label="${i+1}番目の${e.note==='R'?'休み':NOTES[e.note][0]}を削除">${e.note==='R'?'休':NOTES[e.note][0]}<small>${e.beats}拍 ×</small></button>`).join(''):'<p>まずはソ・ラ・シの３つから。上の音を押して入れよう。</p>'}</div>${notes.length?'<p class="muted">上の音のチップを押すと、その音を消せます。</p>':''}${player(notes)}<div class="hint inquiry"><b>今日の実験</b><p>最後の１音を変えてみよう。「まだ続きそう」「終わった感じ」の違いはある？</p></div></section><section class="research"><span class="eyebrow">DISCOVERY NOTE</span><h2>発見ノート</h2><label class="field-label" for="research-prompt">調べること</label><select id="research-prompt">${LESSONS.filter(l=>l.world===9).map(l=>`<option value="${l.id}">${l.title}</option>`).join('')}</select><p id="research-question">${LESSONS[72].question}</p><label class="field-label" for="research-note">予想 → 試したこと → 結果 → 次の問い</label><textarea id="research-note" rows="10" maxlength="1600" placeholder="予想：最後をソにすると…&#10;試したこと：…&#10;結果：…&#10;次は：…">${esc(state.notes['w10-1']||'')}</textarea><button class="button primary" data-action="save-research">発見をのこす</button><button class="text-button" data-lesson="w10-1">研究のチャレンジへ →</button></section></div>`;}
function stampsView(){const xp=earnedPoints(),done=completed(state),all=[...Object.entries(state.records).map(([id,r])=>[id,{...r,type:'lesson'}]),...Object.entries(state.songRecords||{}).map(([id,r])=>[id,{...r,type:'song'}])].sort((a,b)=>b[1].date.localeCompare(a[1].date));return `${heading('MY COLLECTION','スタンプ帳','練習も、発見も、きみだけの大切な足あと。')}<div class="stat-row"><div><span>ぼうけんレベル</span><b>${Math.floor(xp/100)+1}</b><progress max="100" value="${xp%100}" aria-label="次のレベルまで"></progress><small>次のレベルまで ${100-xp%100} ポイント</small></div><div><span>ためたポイント</span><b>${xp}<small> pt</small></b><small>最高のふりかえりで１課題 最大30pt</small></div><div><span>クリアした挑戦</span><b>${done}<small> / 96</small></b><small>自分の「できた」を集めよう</small></div></div><div class="section-title"><h2>エリアのスタンプ</h2><span>エリアの８つをクリアすると色がつくよ</span></div><div class="stamp-grid">${WORLDS.map(w=>{const n=LESSONS.filter(l=>l.world===w.id&&(state.records[l.id]?.rating||0)>=2).length;return `<button class="stamp-card ${n===8?'earned':''}" data-world="${w.id}" style="--world:${w.color}"><span class="stamp-symbol">${w.icon}</span><b>${w.title}</b><small>${n===8?'✦ エリアクリア！':`${n}/8 ・ あと${8-n}チャレンジ`}</small></button>`;}).join('')}</div><h2>最近の足あと</h2>${all.length?`<div class="history">${all.slice(0,20).map(([id,r])=>`<article><span class="history-mark">${r.rating===3?'★':r.rating===2?'✓':'↻'}</span><div><button class="text-button" ${r.type==='song'?`data-history-song="${id}"`:`data-lesson="${id}"`}>${esc((r.type==='song'?CURRICULUM_SONGS:LESSONS).find(l=>l.id===id)?.title||'練習記録')}</button><p>${esc(r.reflection||'今日もひとつ、挑戦した。')}</p><small>${new Date(r.date).toLocaleDateString('ja-JP')} ・ ${badge(r)} ・ ${r.attempts}回挑戦</small></div></article>`).join('')}</div>`:'<div class="empty-state"><span>✦</span><h3>最初の足あとをのこそう</h3><p>むずかしかったことも、記録して大丈夫。</p><button class="button primary" data-lesson="w1-1">最初のチャレンジへ</button></div>'}`;}
function guideView(){return `${heading('FOR TEACHERS','先生へ・記録の設定','ジャーマン式ソプラノリコーダー／小学校３〜６年生＋発展')}<div class="guide-grid"><section class="panel"><h2>授業での使い方</h2><ol><li>全体で今日の音・聴きどころを確認（５分）。</li><li>おすすめや好きなエリアで個別練習（10〜15分）。</li><li>ペアで聴き、具体的な気づきを交換（５〜10分）。</li><li>曲・合奏・創作に戻って試す（10分）。</li><li>自己評価と次の一歩を記録（５分）。</li></ol><p>96課題・288の小ステップ。難しいと回答すると直前の基礎を提案します。曲のひろばは8レベル×5曲で、各レベルの収録曲を3曲（3曲未満なら収録曲すべて）達成すると次へ進みます。楽譜準備中の候補には演奏スタンプを付けません。</p><label class="teacher-switch"><input type="checkbox" id="unlock-all" ${state.settings.allSongsUnlocked?'checked':''}><span><b>曲のひろばを全曲開く</b><small>授業で先生が曲を指定するときに使います。この端末だけに保存されます。</small></span></label><h3>評価の位置づけ</h3><p>児童の自己評価です。マイクでの自動判定や成績評価ではありません。「できた」の目安を児童と共有し、音色・拍・姿勢は先生や友だちの聴取と合わせて確認してください。発展コースの完了は専門演奏家の技能認定を意味しません。</p><h3>授業の音環境</h3><p>お手本は電子音です。音色や息づかいのお手本は先生の実演も使ってください。端末の音量を下げ、お手本を聴く時間と吹く時間を分けると、教室で聴き取りやすくなります。</p></section><section class="panel"><h2>記録を持ち運ぶ</h2><p>このブラウザ内に保存します。名前・メール・学級は入力不要。別端末への自動同期や先生の一括閲覧はありません。共用端末では、使う人ごとにブラウザの利用環境を分けてください。</p><p>ブラウザのデータ削除で消えるため、ときどきバックアップを保存してください。別の端末では、そのファイルを読み込んで続けられます。</p><button class="button primary" data-action="export">↓ 学習記録をバックアップ</button><label class="button secondary file-button">↑ バックアップを読みこむ<input type="file" id="import-file" accept="application/json,.json"></label><p class="muted">読みこむ前に確認します。今の記録は置き換わります。</p><button class="text-button danger" data-action="reset">この端末の記録をリセット</button></section><section class="panel"><h2>教材と運指の範囲</h2><p>使用楽器はAULOS 702B(G)・ジャーマン式。低いド〜最高音のレの27音について、アウロス公開運指表（販売店転載）と照合した図を表示します。二重穴を片方だけ閉じる半音にも対応。最高音域のド♯は資料に裏穴の違いがあり、機種付属表の確認が必要です。実機の音程測定や替え指の網羅は行っていません。</p><p>40曲候補のうち21曲に、出典と採用範囲を示した学習用単旋律を収録しています。残る19曲は公開用の原典・権利確認が済むまで楽譜準備中です。歌詞・教科書の編曲・市販音源は使用していません。自由練習は創作・伝承曲の12曲です。</p><ul><li><a href="https://www.kyogei.co.jp/textbook/es/es-r6/songlist" target="_blank" rel="noopener">教育芸術社：令和6年度版 教材曲一覧</a></li><li><a href="${SOURCE}" target="_blank" rel="noopener">AULOS：702B(G)の製品情報</a></li><li><a href="${PDF}" target="_blank" rel="noopener">アウロスのドイツ式運指表（販売店転載）</a></li><li><a href="https://www.yamaha.com/ja/musical_instrument_guide/recorder/play/" target="_blank" rel="noopener">ヤマハ：構え方と息づかい</a></li></ul><p class="muted">参照確認：2026年9月26日。曲集の候補は学校提供の目次画像で確認。小ステップの構成・練習フレーズは本サイト独自です。</p></section><section class="panel"><h2>学びの見取り</h2><table><thead><tr><th>観点</th><th>確かめること</th></tr></thead><tbody><tr><td>音づくり</td><td>穴を閉じ、息を調整して音を保てる</td></tr><tr><td>技能</td><td>指・舌・拍をそろえ、同じように再現できる</td></tr><tr><td>表現</td><td>曲のまとまりを捉え、意図を音にできる</td></tr><tr><td>探究・協働</td><td>条件を比べ、気づきを説明し、聴き合える</td></tr></tbody></table><p>課題は最大30pt、曲は最大15ptの最高到達分。くり返しで増やせず、苦手に戻っても獲得済みポイントは減りません。ランキングはありません。</p></section></div>`;}
function render(){const views={map:mapView,songs:songsView,fingers:fingersView,lab:labView,stamps:stampsView,guide:guideView};$('#app').innerHTML=shell(views[page]());$('#lesson-dialog').addEventListener('cancel',()=>{stopAudio();activeLesson=null;});$('#confirm-dialog').addEventListener('cancel',()=>{importCandidate=null;});}
function confirmDialog(title,body,action,label){const d=$('#confirm-dialog');d.innerHTML=`<div class="modal-header"><h2 id="confirm-title">${title}</h2><button class="icon-button" data-action="cancel-confirm" aria-label="確認を閉じる">×</button></div><div class="modal-body"><p>${body}</p><div class="save-row"><button class="button secondary" data-action="cancel-confirm">やめる</button><button class="button primary" data-action="${action}">${label}</button></div></div>`;d.showModal();}
async function canon(){stopAudio();const generation=audioGeneration;try{await ctx();if(generation!==audioGeneration)return;const s=SONGS.find(s=>s.id===selectedSong),events=parseNotes(s.notes),beat=60/state.settings.tempo,start=audio.currentTime+.1;playing=true;for(let i=0;i<4;i++)tone('B5',start+i*beat,.055,true);let end=0;for(const offset of [4,12]){let time=offset*beat;for(const e of events){tone(e.note,start+time,e.beats*beat*.85);time+=e.beats*beat;}end=time;}$$('.player-status').forEach(e=>e.textContent='８拍あとに、２人目が同じ曲で入ります。');timers.push(setTimeout(stopAudio,end*1000+200));}catch(e){stopAudio();toast(e.message);}}
document.addEventListener('click',async e=>{const t=e.target.closest('button,a,[data-note]');if(!t)return;if(t.dataset.page){e.preventDefault();route(t.dataset.page);return;}if(t.dataset.world!==undefined){world=Number(t.dataset.world);if(page!=='map'){route('map');}else{render();}$('.area-panel').scrollIntoView({behavior:'smooth',block:'start'});return;}if(t.dataset.lesson){openLesson(t.dataset.lesson);return;}if(t.dataset.songLevel!==undefined){const level=Number(t.dataset.songLevel);if(level!==0&&!songLevelUnlocked(state,level)){toast('ひとつ前のレベルの収録曲を進めよう。目標は最大3曲だよ。');return;}stopAudio();selectedSongLevel=level;const songs=level===0?ALL_SONGS.filter(song=>song.songLevel===0):CURRICULUM_SONGS.filter(song=>song.songLevel===level);selectedSong=(songs.find(s=>s.mode==='play')||songs[0]).id;segment='all';chunkBeats=(ALL_SONGS.find(s=>s.id===selectedSong)?.meter||4)*2;scoreScale=1;const selected=ALL_SONGS.find(s=>s.id===selectedSong);const first=selected.notes?parseNotes(selected.notes).find(n=>n.note!=='R'):null;if(first)chosenNote=first.note;render();return;}if(t.dataset.historySong){const song=ALL_SONGS.find(s=>s.id===t.dataset.historySong);if(song){selectedSong=song.id;selectedSongLevel=song.songLevel;segment='all';chunkBeats=(song.meter||4)*2;scoreScale=1;const first=song.notes?parseNotes(song.notes).find(e=>e.note!=='R'):null;if(first)chosenNote=first.note;route('songs');}return;}if(t.dataset.song){stopAudio();selectedSong=t.dataset.song;segment='all';chunkBeats=(ALL_SONGS.find(s=>s.id===selectedSong)?.meter||4)*2;scoreScale=1;const song=ALL_SONGS.find(s=>s.id===selectedSong),first=song?.notes?parseNotes(song.notes).find(n=>n.note!=='R'):null;if(first)chosenNote=first.note;render();return;}if(t.dataset.rateSong){const song=CURRICULUM_SONGS.find(s=>s.id===selectedSong);if(!song||song.mode!=='play')return;if(Number(t.dataset.rateSong)>1&&!canRateSong(song)){toast('6つの手順を試してから、収録部分を通してみよう。');return;}const next=song.songLevel+1,wasUnlocked=next>8||songLevelUnlocked(state,next),before=earnedPoints();recordSong(state,song.id,Number(t.dataset.rateSong));save();const gained=earnedPoints()-before,nowUnlocked=next>8||songLevelUnlocked(state,next);render();toast(!wasUnlocked&&nowUnlocked?`LEVEL ${next} が開いたよ！新しい5曲に挑戦しよう ✦`:`演奏スタンプを記録したよ。${gained>0?' ＋'+gained+'ポイント ✦':''}`);return;}if(t.dataset.pickNote){singleNote(t.dataset.pickNote);return;}if(t.dataset.note){if(t.dataset.note!=='R')singleNote(t.dataset.note);return;}if(t.dataset.addNote){if(state.composition.length>=32)return;stopAudio();state.composition.push({note:t.dataset.addNote,beats:composerBeat});save();render();return;}if(t.dataset.removeNote!==undefined){stopAudio();state.composition.splice(Number(t.dataset.removeNote),1);save();render();return;}
switch(t.dataset.action){case'ready-song':{stopAudio();const song=CURRICULUM_SONGS.find(s=>s.mode==='play'&&songLevelUnlocked(state,s.songLevel));selectedSong=song.id;selectedSongLevel=song.songLevel;segment='all';chunkBeats=song.meter*2;scoreScale=1;chosenNote=parseNotes(song.notes).find(e=>e.note!=='R').note;render();break;}case'play':play();break;case'stop':stopAudio();break;case'score-fit':fitScore();break;case'score-out':setScoreScale(Math.min(scoreScale,Math.max(.25,scoreScale-.1)));break;case'score-in':setScoreScale(scoreScale+.1);break;case'score-reset':setScoreScale(1);break;case'close-lesson':closeLesson();break;case'save-lesson':saveLesson();break;case'names':{state.settings.names=!state.settings.names;save();if(activeLesson){$$('.note-label').forEach(el=>{const n=el.closest('[data-note]').dataset.note;el.textContent=state.settings.names?(n==='R'?'休み':NOTES[n][0]):'';});t.textContent=`音名を${state.settings.names?'かくす':'出す'}`;}else{stopAudio();render();}break;}case'save-research':state.notes[$('#research-prompt').value]=$('#research-note').value;save();toast('発見をのこしたよ。次の実験も楽しみだね！');break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='recorder-quest-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('バックアップをダウンロードしました。');break;}case'reset':confirmDialog('記録をリセットする？','このブラウザの学習記録・曲・発見ノートが消えます。必要なら、先にバックアップしてください。','confirm-reset','リセットする');break;case'confirm-reset':state=fresh();save();render();toast('新しいぼうけんを始められるよ。');break;case'cancel-confirm':$('#confirm-dialog').close();importCandidate=null;break;case'confirm-import':if(importCandidate){state=importCandidate;importCandidate=null;save();render();toast('記録を読みこみました。');}break;case'canon':canon();break;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-note]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('input',e=>{if(e.target.id==='tempo'){stopAudio();state.settings.tempo=Number(e.target.value);e.target.nextElementSibling.value=state.settings.tempo;save();}if(e.target.id==='composition-title'){state.compositionTitle=e.target.value;save();}if(e.target.id==='research-note'){state.notes[$('#research-prompt').value]=e.target.value;save();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset?.songStep!==undefined){const song=CURRICULUM_SONGS.find(s=>s.id===selectedSong);if(song){state.songSteps??={};state.songSteps[song.id]??=song.steps.map(()=>false);state.songSteps[song.id][Number(t.dataset.songStep)]=t.checked;save();$$('[data-rate-song]').forEach(b=>b.disabled=Number(b.dataset.rateSong)>1&&!canRateSong(song));}return;}if(t.id==='duet-part'){stopAudio();duetPart=t.value;segment='all';render();return;}if(t.id==='chunk-beats'){stopAudio();chunkBeats=Number(t.value);segment='0';render();return;}if(t.matches('.step-check,input[name="rating"]'))checkLesson();if(t.id==='loop')loop=t.checked;if(t.id==='click-track'){clickTrack=t.checked;stopAudio();}if(t.id==='segment'){stopAudio();segment=t.value;render();}if(t.id==='articulation'){stopAudio();articulation=t.value;}if(t.id==='composer-beat')composerBeat=Number(t.value);if(t.id==='unlock-all'){state.settings.allSongsUnlocked=t.checked;save();toast(t.checked?'40曲をすべて開きました。':'曲のレベルアップ設定に戻しました。');}if(t.id==='research-prompt'){$('#research-note').value=state.notes[t.value]||'';$('#research-question').textContent=LESSONS.find(l=>l.id===t.value).question;}
if(t.id==='import-file'){const f=t.files[0];if(!f)return;try{if(f.size>1000000)throw Error('ファイルが大きすぎます（上限１MB）');importCandidate=validateBackup(JSON.parse(await f.text()));confirmDialog('バックアップを読みこむ？',`${Object.keys(importCandidate.records).length}件の記録を読み込みます。今の記録・曲・発見ノートは置き換わります。`,'confirm-import','読みこむ');}catch(e){toast(e.message||'バックアップを読み込めませんでした。');}t.value='';}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(nav.some(n=>n[0]===p)||p==='guide'){if(page!==p){stopAudio();activeLesson=null;page=p;render();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio();});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_learning_progress',description:'Read device-local recorder learning progress and recommended lesson.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({completed:completed(state),points:earnedPoints(),recommended:recommend(state).lesson.id})},{name:'open_recorder_lesson',description:'Open a lesson without completing it or changing learning records.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!LESSONS.some(l=>l.id===input.lessonId))throw Error('Unknown lesson');if(activeLesson)closeLesson();openLesson(input.lessonId);return {opened:input.lessonId};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
